B.Xg=new A.t2("function createFamilyForm() {\n  var form = FormApp.create('Family Tree - Family details');\n  form.setDescription('Please fill in your family details. Fill it again for each household.');\n  form.addTextItem().setTitle('Your full name').setRequired(true);\n  form.addMultipleChoiceItem().setTitle('Gender').setChoiceValues(['Male', 'Female']);\n  form.addDateItem().setTitle('Date of birth');\n  form.addMultipleChoiceItem().setTitle('Passed away').setChoiceValues(['No', 'Yes']);\n  form.addDateItem().setTitle('Date of passing');\n  form.addTextItem().setTitle('Lives in (town / city)');\n  form.addTextItem().setTitle(\"Father's full name\");\n  form.addTextItem().setTitle(\"Mother's full name\");\n  form.addTextItem().setTitle('Husband / Wife full name');\n  form.addParagraphTextItem().setTitle('Children')\n      .setHelpText('One per line: name, son or daughter, date of birth. Example: Ayesha, daughter, 12/03/2005');\n  form.addTextItem().setTitle('Mobile number (with country code)');\n  form.addMultipleChoiceItem().setTitle('Blood group')\n      .setChoiceValues(['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-', \"Don't know\"]);\n  var sheet = SpreadsheetApp.create('Family Tree - Answers');\n  form.setDestination(FormApp.DestinationType.SPREADSHEET, sheet.getId());\n  Logger.log('Form link to share: ' + form.getPublishedUrl());\n  Logger.log('Answers sheet: ' + sheet.getUrl());\n}\n")
